sys_variable_value.value:
(function(outputs, steps, stepResult, assertEqual)
{
	var test = new x_snc_devtools.TestAPI(outputs, steps, stepResult, assertEqual);
	
	test.SetResult(true);
	
	function TestCase_GetCleanPackageObject(vPackageObject,vExpected)
	{
		function TestCase_GetCleanPackageObject_CheckResult(vInput,vExpected,vResult)
		{
			if (vExpected == false)
			{
				return (vExpected == vResult);
			}
			if (IsObject(vPackageObject) == false)
			{
				if (IsValidRecord(vPackageObject) == false)
				{
					return IsEqual(vPackageObject,vResult); 
				}
			}
			var aKeys = GetKeys(vResult);
			if (ArrayValueExists(aKeys,'template') == true)
			{
				return false;
			}
			if (ArrayValueExists(aKeys,'sys_mod_count') == true)
			{
				return false;
			}	
			if (ArrayValueExists(aKeys,'action') == true)
			{
				return false;
			}				
			return true;
		}
		
		test.TestCase(
			'Function GetCleanPackageObject()',
			GetCleanPackageObject,
			{
				'vPackageObject': vPackageObject
			},
			vExpected,
			TestCase_GetCleanPackageObject_CheckResult);
	}
		
	TestCase_GetCleanPackageObject(null,false);

	TestCase_GetCleanPackageObject({
		sys_code: null,
		sys_id: '1234',
		name: 'Name',
		template: '',
		active: true,
		action: 'INSERT OR UPDATE',
		sys_mod_count: 100
		},true);
	
	TestCase_GetCleanPackageObject(GetAppRecord('x_snc_deployer'),true);
	
	return test.GetResult();
	
})(outputs, steps, stepResult, assertEqual);
